export type ProductAccessState =
  | 'signed-out'
  | 'checking'
  | 'not-purchased'
  | 'purchased'
  | 'owner'
  | 'error';

export type ProductCtaAction = 'login' | 'purchase' | 'open' | 'manage' | 'none';

export type ProductCtaState = {
  action: ProductCtaAction;
  disabled: boolean;
  label: string;
  reason: string | null;
};

export type ProductPlan = {
  name: string;
  price: number | null;
  currency: string | null;
  interval: string | null;
  features: string[];
  rawIndex: number;
};

export type ProductContentItem = {
  title: string;
  detail: string | null;
};

export type ProductContentGroup = {
  title: string;
  items: ProductContentItem[];
};

export type ProductFaqItem = {
  question: string;
  answer: string;
};

export type ProductPageModel = {
  about: string | null;
  category: string | null;
  contentGroups: ProductContentGroup[];
  currency: string;
  delivery: string | null;
  faq: ProductFaqItem[];
  images: string[];
  inclusions: ProductContentItem[];
  isFree: boolean;
  isSubscription: boolean;
  plans: ProductPlan[];
  price: number | null;
  refund: string | null;
  shortDescription: string | null;
  support: string | null;
  typeLabel: string;
};

const isRecord = (value: unknown): value is Record<string, any> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

const cleanText = (value: unknown): string | null =>
  typeof value === 'string' && value.trim() ? value.trim() : null;

const cleanUrl = (value: unknown): string | null => {
  const url = cleanText(value);
  return url && !url.startsWith('data:text/html') ? url : null;
};

const finiteAmount = (value: unknown): number | null => {
  if (value === null || value === undefined || value === '') return null;
  const amount = Number(value);
  return Number.isFinite(amount) && amount >= 0 ? amount : null;
};

const firstText = (...values: unknown[]) => {
  for (const value of values) {
    const candidate = cleanText(value);
    if (candidate) return candidate;
  }
  return null;
};

const recordArray = (value: unknown): Record<string, any>[] => {
  if (Array.isArray(value)) return value.filter(isRecord);
  return [];
};

const stringArray = (value: unknown): string[] => {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => {
      if (typeof item === 'string') return cleanText(item);
      if (!isRecord(item)) return null;
      return firstText(item.title, item.name, item.label, item.filename, item.file_name);
    })
    .filter((item): item is string => Boolean(item));
};

const uniqueItems = (items: ProductContentItem[]) => {
  const seen = new Set<string>();
  return items.filter((item) => {
    const key = `${item.title.toLowerCase()}::${item.detail?.toLowerCase() || ''}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const typeLabel = (value: unknown) => {
  const normalized = String(value || 'product').toLowerCase();
  const labels: Record<string, string> = {
    affiliate: 'Affiliate product',
    apps: 'App',
    asset_3d: '3D asset',
    bundle: 'Bundle',
    community: 'Community',
    course: 'Course',
    digital: 'Digital product',
    music: 'Audio',
    physical: 'Physical product',
    product: 'Product',
    service: 'Service',
    software: 'Software',
    virtual: 'Virtual item',
  };
  return labels[normalized] || normalized.replace(/[_-]+/g, ' ').replace(/^./, (letter) => letter.toUpperCase());
};

const planRows = (listing: Record<string, any>, metadata: Record<string, any>): ProductPlan[] => {
  const rows = recordArray(listing.plans).length
    ? recordArray(listing.plans)
    : recordArray(metadata.plans);
  return rows.map((plan, rawIndex) => ({
    name: firstText(plan.name, plan.title) || `Option ${rawIndex + 1}`,
    price: finiteAmount(plan.price),
    currency: firstText(plan.currency, listing.currency, listing.base_currency)?.toUpperCase() || null,
    interval: firstText(plan.billing_interval, plan.interval, metadata.billing_interval, metadata.subscription_interval),
    features: stringArray(plan.features),
    rawIndex,
  }));
};

const faqRows = (metadata: Record<string, any>): ProductFaqItem[] =>
  recordArray(metadata.faq).concat(recordArray(metadata.faqs))
    .map((item) => ({
      question: firstText(item.question, item.title),
      answer: firstText(item.answer, item.response, item.content),
    }))
    .filter((item): item is ProductFaqItem => Boolean(item.question && item.answer));

const courseContent = (metadata: Record<string, any>) => {
  const course = isRecord(metadata.course) ? metadata.course : {};
  const modules = recordArray(course.modules).length
    ? recordArray(course.modules)
    : recordArray(metadata.modules);
  if (!modules.length) return null;
  return {
    title: 'Course preview',
    items: modules.slice(0, 6).map((module, index) => {
      const lessons = recordArray(module.lessons);
      const lessonTitles = lessons.map((lesson) => firstText(lesson.title, lesson.name)).filter(Boolean);
      return {
        title: firstText(module.title, module.name) || `Module ${index + 1}`,
        detail: lessonTitles.length
          ? `${lessons.length} lesson${lessons.length === 1 ? '' : 's'} · ${lessonTitles.slice(0, 3).join(', ')}${lessonTitles.length > 3 ? '…' : ''}`
          : lessons.length
            ? `${lessons.length} lesson${lessons.length === 1 ? '' : 's'}`
            : null,
      };
    }),
  } satisfies ProductContentGroup;
};

const packageContent = (metadata: Record<string, any>) => {
  const packages = recordArray(metadata.packages);
  if (!packages.length) return null;
  return {
    title: 'Available packages',
    items: packages.slice(0, 6).map((item, index) => {
      const details = [
        item.deliveryTime ? `${item.deliveryTime} day delivery` : null,
        item.revisions ? `${item.revisions} revision${Number(item.revisions) === 1 ? '' : 's'}` : null,
        ...stringArray(item.features).slice(0, 2),
      ].filter(Boolean);
      return {
        title: firstText(item.name, item.title) || `Package ${index + 1}`,
        detail: details.length ? details.join(' · ') : null,
      };
    }),
  } satisfies ProductContentGroup;
};

const genericContentGroup = (
  title: string,
  value: unknown,
  detailKeys: string[] = [],
): ProductContentGroup | null => {
  const records = recordArray(value);
  const strings = stringArray(value);
  if (!records.length && !strings.length) return null;
  if (records.length) {
    const items = records.map((item, index) => ({
      title: firstText(item.title, item.name, item.label, item.filename, item.file_name) || `${title.replace(/s$/, '')} ${index + 1}`,
      detail: firstText(...detailKeys.map((key) => item[key])),
    }));
    return { title, items };
  }
  return { title, items: strings.map((item) => ({ title: item, detail: null })) };
};

export const getProductPageModel = (input: unknown): ProductPageModel => {
  const listing = isRecord(input) ? input : {};
  const metadata = isRecord(listing.metadata) ? listing.metadata : {};
  const course = isRecord(metadata.course) ? metadata.course : {};
  const pricing = isRecord(listing._pricing) ? listing._pricing : {};
  const price = finiteAmount(pricing.currentPrice ?? listing.price);
  const currency = firstText(listing.currency, listing.base_currency, metadata.currency, metadata.base_currency)?.toUpperCase() || 'EUR';
  const rawImages = [
    ...(Array.isArray(listing.images) ? listing.images : []),
    ...(Array.isArray(metadata.images) ? metadata.images : []),
    listing.image,
    listing.image_url,
    listing.thumbnail_url,
    listing.thumbnail,
  ];
  const images = [...new Set(rawImages.map(cleanUrl).filter((item): item is string => Boolean(item)))];
  const plans = planRows(listing, metadata);
  const rawType = String(listing.type || 'product').toLowerCase();
  const modules = recordArray(course.modules).length ? recordArray(course.modules) : recordArray(metadata.modules);
  const lessonCount = modules.reduce((total, module) => total + recordArray(module.lessons).length, 0);

  const inclusions: ProductContentItem[] = [];
  stringArray(metadata.includes)
    .concat(stringArray(metadata.included), stringArray(metadata.includedItems), stringArray(metadata.deliverables), stringArray(metadata.features))
    .forEach((item) => inclusions.push({ title: item, detail: null }));

  if (modules.length) {
    inclusions.push({
      title: 'Course content',
      detail: `${modules.length} module${modules.length === 1 ? '' : 's'}${lessonCount ? ` · ${lessonCount} lesson${lessonCount === 1 ? '' : 's'}` : ''}`,
    });
  }
  if (rawType === 'community') inclusions.push({ title: 'Community access', detail: firstText(metadata.access_period, metadata.accessPeriod) });
  if (firstText(metadata.mainFileUrl, metadata.fileUrl, metadata.file_url, listing.file_url)) {
    inclusions.push({ title: 'Download', detail: firstText(metadata.format, metadata.fileType, metadata.file_type) });
  }
  if (recordArray(metadata.files).length) inclusions.push({ title: 'Downloads', detail: `${recordArray(metadata.files).length} file${recordArray(metadata.files).length === 1 ? '' : 's'}` });
  if (recordArray(metadata.events).length) inclusions.push({ title: 'Events', detail: `${recordArray(metadata.events).length} included` });
  if (recordArray(metadata.calls).length) inclusions.push({ title: 'Calls', detail: `${recordArray(metadata.calls).length} included` });
  if (metadata.certificate === true || metadata.certificate_included === true) inclusions.push({ title: 'Certificate', detail: null });
  if (metadata.updatesIncluded === true || metadata.updates_included === true || metadata.freeUpdates === true) inclusions.push({ title: 'Updates', detail: 'Included' });
  if (firstText(metadata.support, metadata.support_contact, metadata.supportEmail, metadata.support_email)) inclusions.push({ title: 'Seller support', detail: null });

  const contentGroups = [
    courseContent(metadata),
    packageContent(metadata),
    genericContentGroup('Downloads', metadata.files, ['format', 'file_type', 'size']),
    genericContentGroup('Community spaces', metadata.channels, ['description']),
    genericContentGroup('Events', metadata.events, ['date', 'starts_at', 'description']),
    genericContentGroup('Calls', metadata.calls, ['duration', 'description']),
    genericContentGroup('Available variants', metadata.variations, ['value', 'description']),
  ].filter((group): group is ProductContentGroup => Boolean(group?.items.length));

  const description = firstText(listing.description, metadata.description);
  const explicitShortDescription = firstText(listing.short_description, metadata.short_description, metadata.shortDescription);
  const shortDescription = explicitShortDescription || (description && description.length > 190 ? `${description.slice(0, 187).trimEnd()}…` : description);
  const isSubscription = Boolean(
    String(listing.pricing_type || '').toLowerCase() === 'subscription'
    || listing.billing_interval
    || metadata.billing_interval
    || metadata.subscription_interval,
  );
  const instantDelivery = metadata.delivery_type === 'instant'
    || metadata.access === 'instant'
    || metadata.instant_delivery === true
    || metadata.instant_access === true;
  const delivery = instantDelivery
    ? 'Access starts immediately after a successful checkout.'
    : firstText(
        metadata.delivery,
        metadata.deliveryDetails,
        metadata.delivery_details,
        metadata.deliveryTime ? `${metadata.deliveryTime} day delivery` : null,
        metadata.access_period,
        metadata.accessPeriod,
      );
  const refund = firstText(
    metadata.refundPolicy,
    metadata.refund_policy,
    metadata.returnPolicy,
    metadata.return_policy,
    metadata.returnPeriod ? `${metadata.returnPeriod} day return period` : null,
  );
  const support = firstText(metadata.support, metadata.support_contact, metadata.supportEmail, metadata.support_email);

  return {
    about: description,
    category: firstText(listing.category),
    contentGroups,
    currency,
    delivery,
    faq: faqRows(metadata),
    images,
    inclusions: uniqueItems(inclusions).slice(0, 12),
    isFree: price === 0,
    isSubscription,
    plans,
    price,
    refund,
    shortDescription,
    support,
    typeLabel: typeLabel(listing.type),
  };
};

export const getProductCtaState = ({
  accessState,
  isAuthenticated,
  isFree,
  isSubscription,
  paymentReady,
  paymentStatusError = false,
  priceAvailable,
  productType,
}: {
  accessState: ProductAccessState;
  isAuthenticated: boolean;
  isFree: boolean;
  isSubscription: boolean;
  paymentReady: boolean | null;
  paymentStatusError?: boolean;
  priceAvailable: boolean;
  productType: string;
}): ProductCtaState => {
  if (accessState === 'owner') {
    return { action: 'manage', disabled: false, label: 'Manage product', reason: 'Open this product in your Workspace.' };
  }
  if (accessState === 'purchased') {
    return { action: 'open', disabled: false, label: 'Open product', reason: 'This product is already in your library.' };
  }
  if (accessState === 'checking') {
    return { action: 'none', disabled: true, label: 'Checking your access', reason: 'Confirming whether this product is already in your library.' };
  }
  if (accessState === 'error') {
    return { action: 'none', disabled: true, label: 'Access check unavailable', reason: 'Your existing access could not be verified safely.' };
  }
  if (!priceAvailable) {
    return { action: 'none', disabled: true, label: 'Currently unavailable', reason: 'The seller has not provided a valid checkout price.' };
  }
  if (isFree && !isAuthenticated) {
    return { action: 'login', disabled: false, label: 'Log in to continue', reason: 'A Wersee account is required to add free access to your library.' };
  }
  if (!isFree && paymentReady === null) {
    return { action: 'none', disabled: true, label: 'Checking payment availability', reason: 'Wersee is confirming the seller’s payment status.' };
  }
  if (!isFree && paymentStatusError) {
    return { action: 'none', disabled: true, label: 'Payment status unavailable', reason: 'Wersee could not safely verify the seller’s payment status. Try again later.' };
  }
  if (!isFree && paymentReady === false) {
    return { action: 'none', disabled: true, label: 'Payment unavailable', reason: 'This seller cannot accept payments for this product yet.' };
  }
  if (String(productType).toLowerCase() === 'community' || isSubscription) {
    return { action: 'purchase', disabled: false, label: 'Join', reason: null };
  }
  if (isFree) {
    return { action: 'purchase', disabled: false, label: 'Get access', reason: null };
  }
  return { action: 'purchase', disabled: false, label: 'Buy now', reason: null };
};
