import {
  getProductCtaState,
  getProductPageModel,
  type ProductAccessState,
  type ProductContentItem,
  type ProductCtaState,
  type ProductPlan,
} from '../../../lib/productPage';

type StreamlinedProductDetailProps = {
  accessState: ProductAccessState;
  listing: any;
  onContactSeller: () => void;
  onEnroll: (planIndex?: number) => void;
  onLogin: () => void;
  onManageProduct: () => void;
  onOpenProduct: () => void;
  onRetryAccess: () => void;
  onReviewAdded?: () => void;
  onShare: () => void;
  paymentReady: boolean | null;
  paymentStatusError?: boolean;
  relatedListings: any[];
  reviews: any[];
  sellerType: 'business' | 'consumer' | null;
  userId?: string | null;
};

type PlanSelectorProps = {
  plans: ProductPlan[];
  selectedIndex: number | null;
  onSelect: (index: number) => void;
};

type PurchasePanelProps = {
  cta: ProductCtaState;
  currency: string;
  inclusions: ProductContentItem[];
  isOnSale: boolean;
  originalPrice: number | null;
  plans: ProductPlan[];
  price: number | null;
  priceSuffix: string | null;
  selectedPlanIndex: number | null;
  delivery: string | null;
  refund: string | null;
  onPrimaryAction: () => void;
  onRetryAccess: () => void;
  onSelectPlan: (index: number) => void;
};

const focusRing = 'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-300 focus-visible:ring-offset-2 focus-visible:ring-offset-[#09090b]';

const ProductVideo = ({ url, title }: { url: string; title: string }) => {
  const directVideo = /\.(mp4|webm|ogg)(?:$|\?)/i.test(url);
  const youtubeId = url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([A-Za-z0-9_-]{6,})/)?.[1];
  const vimeoId = url.match(/vimeo\.com\/(?:video\/)?(\d+)/)?.[1];

  if (directVideo) {
    return (
      <video className="aspect-video w-full rounded-2xl bg-black object-contain" controls preload="metadata">
        <source src={url} />
      </video>
    );
  }
  if (youtubeId || vimeoId) {
    const src = youtubeId
      ? `https://www.youtube-nocookie.com/embed/${youtubeId}`
      : `https://player.vimeo.com/video/${vimeoId}`;
    return (
      <iframe
        className="aspect-video w-full rounded-2xl bg-black"
        src={src}
        title={`${title} video`}
        loading="lazy"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
      />
    );
  }
  return (
    <a
      href={url}
      target="_blank"
      rel="noopener noreferrer"
      className={`inline-flex min-h-12 items-center gap-2 rounded-xl border border-white/10 px-4 text-sm font-semibold text-white transition hover:bg-white/[0.06] ${focusRing}`}
    >
      <Video className="h-4 w-4" /> Open product video <ExternalLink className="h-4 w-4" />
    </a>
  );
};

const PlanSelector = ({ plans, selectedIndex, onSelect }: PlanSelectorProps) => {
  if (!plans.length) return null;
  return (
    <fieldset className="space-y-2.5">
      <legend className="mb-2 text-xs font-semibold uppercase tracking-[0.18em] text-white/45">Choose access</legend>
      {plans.map((plan) => {
        const selected = selectedIndex === plan.rawIndex;
        return (
          <button
            key={`${plan.rawIndex}:${plan.name}`}
            type="button"
            aria-pressed={selected}
            onClick={() => onSelect(plan.rawIndex)}
            className={`w-full rounded-xl border px-4 py-3.5 text-left transition ${focusRing} ${selected ? 'border-indigo-300/60 bg-indigo-400/[0.12]' : 'border-white/10 bg-white/[0.025] hover:border-white/20 hover:bg-white/[0.045]'}`}
          >
            <span className="flex items-start justify-between gap-3">
              <span className="min-w-0">
                <span className="block truncate text-sm font-semibold text-white">{plan.name}</span>
                {plan.interval ? <span className="mt-0.5 block text-xs text-white/42">Billed {plan.interval}</span> : null}
              </span>
              <span className="shrink-0 text-sm font-semibold text-white">
                {plan.price === null ? 'Unavailable' : plan.price === 0 ? 'Free' : (
                  <LocalizedPrice amount={plan.price} baseCurrency={plan.currency || 'EUR'} showOriginal={false} />
                )}
              </span>
            </span>
          </button>
        );
      })}
    </fieldset>
  );
};

const PurchasePanel = ({
  cta,
  currency,
  inclusions,
  isOnSale,
  originalPrice,
  plans,
  price,
  priceSuffix,
  selectedPlanIndex,
  delivery,
  refund,
  onPrimaryAction,
  onRetryAccess,
  onSelectPlan,
}: PurchasePanelProps) => (
  <aside className="rounded-3xl border border-white/10 bg-[#121216]/95 p-5 shadow-[0_28px_90px_rgba(0,0,0,.38)] backdrop-blur-xl sm:p-6">
    <div className="border-b border-white/8 pb-5">
      <p className="text-xs font-semibold uppercase tracking-[0.2em] text-white/38">Your access</p>
      <div className="mt-2 flex flex-wrap items-end gap-x-3 gap-y-1">
        {price === null ? (
          <span className="text-2xl font-semibold text-amber-200">Price unavailable</span>
        ) : price === 0 ? (
          <span className="text-4xl font-semibold tracking-[-0.04em] text-white">Free</span>
        ) : (
          <LocalizedPrice amount={price} baseCurrency={currency} className="text-4xl font-semibold tracking-[-0.04em] text-white" />
        )}
        {priceSuffix ? <span className="pb-1 text-sm text-white/42">{priceSuffix}</span> : null}
      </div>
      {isOnSale && originalPrice !== null && price !== null && originalPrice > price ? (
        <p className="mt-1.5 text-sm text-white/42">
          <span className="line-through"><LocalizedPrice amount={originalPrice} baseCurrency={currency} showOriginal={false} /></span>
          <span className="ml-2 text-emerald-300">Current verified offer</span>
        </p>
      ) : null}
    </div>

    <div className="mt-5">
      <PlanSelector plans={plans} selectedIndex={selectedPlanIndex} onSelect={onSelectPlan} />
    </div>

    {inclusions.length ? (
      <ul className="mt-5 space-y-2.5 border-t border-white/8 pt-5" aria-label="Included with purchase">
        {inclusions.slice(0, 5).map((item) => (
          <li key={`${item.title}:${item.detail || ''}`} className="flex gap-2.5 text-sm text-white/68">
            <Check className="mt-0.5 h-4 w-4 shrink-0 text-indigo-300" />
            <span><span className="text-white/88">{item.title}</span>{item.detail ? ` · ${item.detail}` : ''}</span>
          </li>
        ))}
      </ul>
    ) : null}

    <button
      type="button"
      onClick={onPrimaryAction}
      disabled={cta.disabled}
      className={`mt-6 flex min-h-13 w-full items-center justify-center rounded-xl bg-white px-5 text-base font-semibold text-black transition hover:bg-indigo-100 active:translate-y-px disabled:cursor-not-allowed disabled:bg-white/10 disabled:text-white/38 ${focusRing}`}
    >
      {cta.label}
    </button>
    {cta.reason ? <p id="product-cta-reason" className="mt-3 text-center text-xs leading-5 text-white/42">{cta.reason}</p> : null}
    {cta.action === 'none' && cta.label === 'Access check unavailable' ? (
      <button type="button" onClick={onRetryAccess} className={`mx-auto mt-2 flex items-center gap-1.5 text-xs font-semibold text-indigo-300 hover:text-indigo-200 ${focusRing}`}>
        <RefreshCcw className="h-3.5 w-3.5" /> Retry access check
      </button>
    ) : null}

    <div className="mt-5 space-y-3 border-t border-white/8 pt-5 text-xs leading-5 text-white/45">
      <p className="flex gap-2"><LockKeyhole className="mt-0.5 h-4 w-4 shrink-0 text-emerald-300" /><span><strong className="font-semibold text-white/72">Secure payment.</strong> Payment details are handled by Stripe.</span></p>
      {delivery ? <p className="flex gap-2"><Download className="mt-0.5 h-4 w-4 shrink-0 text-indigo-300" /><span>{delivery}</span></p> : null}
      {refund ? <p className="flex gap-2"><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-indigo-300" /><span>{refund}</span></p> : null}
    </div>
  </aside>
);

const sectionIcons = [BookOpen, Download, Users, CalendarDays, Box];

export const StreamlinedProductDetail = ({
  accessState,
  listing,
  onContactSeller,
  onEnroll,
  onLogin,
  onManageProduct,
  onOpenProduct,
  onRetryAccess,
  onReviewAdded,
  onShare,
  paymentReady,
  paymentStatusError = false,
  relatedListings,
  reviews,
  sellerType,
  userId,
}: StreamlinedProductDetailProps) => {
  const navigate = useNavigate();
  const reduceMotion = useReducedMotion();
  const [selectedImage, setSelectedImage] = useState(0);
  const [selectedPlanIndex, setSelectedPlanIndex] = useState<number | null>(() => {
    const plans = getProductPageModel(listing).plans;
    return plans.length ? plans[0].rawIndex : null;
  });
  const [reportOpen, setReportOpen] = useState(false);
  const model = useMemo(() => getProductPageModel(listing), [listing]);
  const selectedPlan = model.plans.find((plan) => plan.rawIndex === selectedPlanIndex) || null;
  const price = selectedPlan?.price ?? model.price;
  const currency = selectedPlan?.currency || model.currency;
  const isFree = price === 0;
  const isSubscription = model.isSubscription || Boolean(selectedPlan?.interval);
  const priceSuffix = isSubscription
    ? `/${selectedPlan?.interval || listing.billing_interval || listing.metadata?.subscription_interval || 'billing period'}`
    : price === null || price === 0
      ? null
      : 'one-time';
  const cta = getProductCtaState({
    accessState,
    isAuthenticated: Boolean(userId),
    isFree,
    isSubscription,
    paymentReady,
    paymentStatusError,
    priceAvailable: price !== null,
    productType: listing.type,
  });
  const pricing = listing._pricing || {};
  const planInclusions = selectedPlan?.features.map((feature) => ({ title: feature, detail: null })) || [];
  const purchaseInclusions = planInclusions.length ? planInclusions : model.inclusions;
  const sellerPath = tryUserProfilePath(listing.seller_handle);
  const sellerName = listing.seller || listing.seller_handle || 'Seller details unavailable';
  const videoUrl = typeof listing.video_url === 'string' && listing.video_url.trim() ? listing.video_url.trim() : null;

  const runPrimaryAction = () => {
    if (cta.action === 'login') onLogin();
    if (cta.action === 'purchase') onEnroll(selectedPlanIndex ?? undefined);
    if (cta.action === 'open') onOpenProduct();
    if (cta.action === 'manage') onManageProduct();
  };

  const trackSellerProfile = () => {
    trackMarketplaceEvent('marketplace_seller_profile_opened', {
      listingId: String(listing.id),
      sellerId: String(listing.seller_id || ''),
      sellerUsername: String(listing.seller_handle || ''),
    });
  };

  const activeImage = model.images[selectedImage] || null;
  const averageRating = reviews.length
    ? reviews.reduce((sum, review) => sum + (Number(review.rating) || 0), 0) / reviews.length
    : null;

  return (
    <div
      className="min-h-screen overflow-x-clip bg-[#09090b] text-white"
      style={{ paddingBottom: 'calc(7.5rem + env(safe-area-inset-bottom, 0px))' }}
    >
      <div className="pointer-events-none fixed inset-x-0 top-0 h-[520px] bg-[radial-gradient(circle_at_18%_0%,rgba(99,102,241,.15),transparent_44%),radial-gradient(circle_at_82%_14%,rgba(14,165,233,.08),transparent_34%)]" aria-hidden="true" />
      <PublicStoreHeader
        sellerAvatar={listing.seller_avatar}
        sellerName={sellerName}
        sellerPath={sellerPath}
        onBack={() => navigate(-1)}
        onShare={onShare}
      />
      <main className="relative mx-auto w-full max-w-[1180px] px-4 pt-5 sm:px-6 sm:pt-7 lg:px-8 lg:pt-10">
        <div className="grid min-w-0 gap-10 lg:grid-cols-[minmax(0,1fr)_348px] lg:gap-12 xl:gap-16">
          <div className="min-w-0">
            <motion.section
              initial={reduceMotion ? false : { opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: reduceMotion ? 0 : 0.35 }}
              aria-label="Product media"
            >
              <div className="relative aspect-[16/10] overflow-hidden rounded-3xl border border-white/10 bg-[#111116] shadow-[0_36px_120px_rgba(0,0,0,.4)]">
                {activeImage ? (
                  <img
                    src={activeImage}
                    alt={`${listing.title}${model.images.length > 1 ? `, image ${selectedImage + 1}` : ''}`}
                    className="h-full w-full object-cover"
                    loading={selectedImage === 0 ? 'eager' : 'lazy'}
                    fetchPriority={selectedImage === 0 ? 'high' : 'auto'}
                    referrerPolicy="no-referrer"
                  />
                ) : (
                  <div className="flex h-full flex-col items-center justify-center gap-3 text-white/24">
                    <ImageIcon className="h-12 w-12" />
                    <span className="text-sm font-medium">No product image provided</span>
                  </div>
                )}
                {model.images.length > 1 ? (
                  <div className="absolute inset-x-4 bottom-4 flex items-center justify-between">
                    <button type="button" aria-label="Previous image" onClick={() => setSelectedImage((current) => (current - 1 + model.images.length) % model.images.length)} className={`grid h-11 w-11 place-items-center rounded-xl border border-white/15 bg-black/55 text-white backdrop-blur-lg transition hover:bg-black/75 ${focusRing}`}>
                      <ChevronLeft className="h-5 w-5" />
                    </button>
                    <span className="rounded-lg bg-black/60 px-2.5 py-1 text-xs font-medium text-white/78 backdrop-blur-lg">{selectedImage + 1} / {model.images.length}</span>
                    <button type="button" aria-label="Next image" onClick={() => setSelectedImage((current) => (current + 1) % model.images.length)} className={`grid h-11 w-11 place-items-center rounded-xl border border-white/15 bg-black/55 text-white backdrop-blur-lg transition hover:bg-black/75 ${focusRing}`}>
                      <ChevronRight className="h-5 w-5" />
                    </button>
                  </div>
                ) : null}
              </div>
              {model.images.length > 1 ? (
                <div className="mt-3 flex max-w-full gap-2 overflow-x-auto pb-1" aria-label="Product image thumbnails">
                  {model.images.map((image, index) => (
                    <button
                      type="button"
                      key={`${image}:${index}`}
                      aria-label={`Show image ${index + 1}`}
                      aria-pressed={selectedImage === index}
                      onClick={() => setSelectedImage(index)}
                      className={`h-16 w-24 shrink-0 overflow-hidden rounded-xl border transition ${focusRing} ${selectedImage === index ? 'border-indigo-300/75 opacity-100' : 'border-white/8 opacity-55 hover:opacity-90'}`}
                    >
                      <img src={image} alt="" loading="lazy" className="h-full w-full object-cover" referrerPolicy="no-referrer" />
                    </button>
                  ))}
                </div>
              ) : null}
              {videoUrl ? <div className="mt-4"><ProductVideo url={videoUrl} title={listing.title} /></div> : null}
            </motion.section>

            <header className="pb-8 pt-8 sm:pt-10">
              <div className="flex flex-wrap items-center gap-2 text-xs font-semibold text-white/50">
                <span className="rounded-md border border-white/10 bg-white/[0.035] px-2.5 py-1.5">{model.typeLabel}</span>
                {model.category ? <span className="rounded-md border border-white/10 bg-white/[0.035] px-2.5 py-1.5">{model.category}</span> : null}
                {averageRating !== null ? (
                  <span className="inline-flex items-center gap-1.5 text-amber-200"><Star className="h-3.5 w-3.5 fill-current" /> {averageRating.toFixed(1)} · {reviews.length} review{reviews.length === 1 ? '' : 's'}</span>
                ) : null}
              </div>
              <h1 className="mt-4 max-w-3xl text-4xl font-semibold leading-[1.04] tracking-[-0.045em] text-white sm:text-5xl lg:text-6xl">{listing.title}</h1>
              {model.shortDescription ? <p className="mt-5 max-w-2xl text-base leading-7 text-white/56 sm:text-lg sm:leading-8">{model.shortDescription}</p> : null}

              {sellerPath ? (
                <Link to={sellerPath} onClick={trackSellerProfile} className={`mt-6 inline-flex max-w-full items-center gap-3 rounded-2xl border border-white/8 bg-white/[0.025] p-2.5 pr-4 transition hover:border-white/16 hover:bg-white/[0.045] ${focusRing}`}>
                  {listing.seller_avatar ? <img src={listing.seller_avatar} alt="" className="h-11 w-11 rounded-xl object-cover" loading="lazy" referrerPolicy="no-referrer" /> : <span className="grid h-11 w-11 place-items-center rounded-xl bg-white/[0.07] text-sm font-semibold text-white">{sellerName.slice(0, 1).toUpperCase()}</span>}
                  <span className="min-w-0">
                    <span className="block truncate text-sm font-semibold text-white">{sellerName}</span>
                    <span className="mt-0.5 flex items-center gap-1.5 text-xs text-white/40">
                      {listing.seller_handle ? `@${listing.seller_handle}` : 'Public seller profile'}
                      {listing.dsa_seller_verification_status === 'verified' ? <><BadgeCheck className="h-3.5 w-3.5 text-indigo-300" /> Verified</> : null}
                    </span>
                  </span>
                  <ChevronRight className="h-4 w-4 shrink-0 text-white/28" />
                </Link>
              ) : (
                <div className="mt-6 flex items-center gap-3 text-sm text-white/48">
                  <span className="grid h-11 w-11 place-items-center rounded-xl bg-white/[0.07] font-semibold text-white">{sellerName.slice(0, 1).toUpperCase()}</span>
                  <span>{sellerName}</span>
                </div>
              )}

              <div className="mt-6 rounded-2xl border border-white/8 bg-white/[0.025] p-4 lg:hidden">
                <div className="flex items-end justify-between gap-3">
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-[0.18em] text-white/36">Price</p>
                    <div className="mt-1 text-3xl font-semibold tracking-[-0.04em] text-white">
                      {price === null ? 'Unavailable' : price === 0 ? 'Free' : <LocalizedPrice amount={price} baseCurrency={currency} />}
                    </div>
                  </div>
                  {priceSuffix ? <span className="pb-1 text-xs text-white/42">{priceSuffix}</span> : null}
                </div>
                {model.plans.length ? <div className="mt-4"><PlanSelector plans={model.plans} selectedIndex={selectedPlanIndex} onSelect={setSelectedPlanIndex} /></div> : null}
                {cta.reason ? <p className="mt-3 text-xs leading-5 text-white/42">{cta.reason}</p> : null}
              </div>
            </header>

            <div className="space-y-12 border-t border-white/8 pt-10">
              {model.about ? (
                <section aria-labelledby="about-product-title">
                  <p className="text-xs font-semibold uppercase tracking-[0.2em] text-indigo-300">The essentials</p>
                  <h2 id="about-product-title" className="mt-2 text-2xl font-semibold tracking-[-0.025em] text-white sm:text-3xl">About this product</h2>
                  <p className="mt-5 whitespace-pre-line text-base leading-8 text-white/58">{model.about}</p>
                </section>
              ) : null}

              {model.inclusions.length ? (
                <section aria-labelledby="included-title">
                  <h2 id="included-title" className="text-2xl font-semibold tracking-[-0.025em] text-white sm:text-3xl">What you get</h2>
                  <div className="mt-6 grid gap-x-8 gap-y-5 sm:grid-cols-2">
                    {model.inclusions.map((item) => (
                      <div key={`${item.title}:${item.detail || ''}`} className="flex gap-3 border-t border-white/8 pt-4">
                        <span className="mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-indigo-400/10 text-indigo-300"><Check className="h-4 w-4" /></span>
                        <div><h3 className="text-sm font-semibold text-white/90">{item.title}</h3>{item.detail ? <p className="mt-1 text-sm leading-6 text-white/42">{item.detail}</p> : null}</div>
                      </div>
                    ))}
                  </div>
                </section>
              ) : null}

              {model.contentGroups.map((group, groupIndex) => {
                const Icon = sectionIcons[groupIndex % sectionIcons.length];
                return (
                  <section key={group.title} aria-labelledby={`content-${groupIndex}`}>
                    <div className="flex items-center gap-3"><Icon className="h-5 w-5 text-indigo-300" /><h2 id={`content-${groupIndex}`} className="text-2xl font-semibold tracking-[-0.025em] text-white">{group.title}</h2></div>
                    <div className="mt-5 divide-y divide-white/8 rounded-2xl border border-white/8 bg-white/[0.018] px-4 sm:px-5">
                      {group.items.map((item, itemIndex) => (
                        <div key={`${item.title}:${itemIndex}`} className="flex gap-4 py-4">
                          <span className="mt-0.5 text-xs font-semibold tabular-nums text-white/24">{String(itemIndex + 1).padStart(2, '0')}</span>
                          <div className="min-w-0"><h3 className="text-sm font-semibold text-white/82">{item.title}</h3>{item.detail ? <p className="mt-1 text-sm leading-6 text-white/42">{item.detail}</p> : null}</div>
                        </div>
                      ))}
                    </div>
                  </section>
                );
              })}

              {(model.delivery || model.refund || model.support || sellerType) ? (
                <section aria-labelledby="delivery-title">
                  <h2 id="delivery-title" className="text-2xl font-semibold tracking-[-0.025em] text-white">Delivery, terms and support</h2>
                  <dl className="mt-5 divide-y divide-white/8 border-y border-white/8">
                    {model.delivery ? <div className="grid gap-2 py-4 sm:grid-cols-[150px_1fr]"><dt className="text-sm font-medium text-white/38">Delivery / access</dt><dd className="text-sm leading-6 text-white/68">{model.delivery}</dd></div> : null}
                    {model.refund ? <div className="grid gap-2 py-4 sm:grid-cols-[150px_1fr]"><dt className="text-sm font-medium text-white/38">Returns / refunds</dt><dd className="text-sm leading-6 text-white/68">{model.refund}</dd></div> : null}
                    {model.support ? <div className="grid gap-2 py-4 sm:grid-cols-[150px_1fr]"><dt className="text-sm font-medium text-white/38">Support</dt><dd className="break-words text-sm leading-6 text-white/68">{model.support}</dd></div> : null}
                    {sellerType ? <div className="grid gap-2 py-4 sm:grid-cols-[150px_1fr]"><dt className="text-sm font-medium text-white/38">Seller type</dt><dd className="text-sm leading-6 text-white/68">{sellerType === 'business' ? 'Business seller' : 'Private seller'}</dd></div> : null}
                  </dl>
                  <button type="button" onClick={onContactSeller} className={`mt-5 inline-flex min-h-12 items-center gap-2 rounded-xl border border-white/10 px-4 text-sm font-semibold text-white/78 transition hover:bg-white/[0.05] hover:text-white ${focusRing}`}><MessageCircle className="h-4 w-4" /> Ask the seller</button>
                </section>
              ) : null}

              {model.faq.length ? (
                <section aria-labelledby="faq-title">
                  <h2 id="faq-title" className="text-2xl font-semibold tracking-[-0.025em] text-white">Frequently asked questions</h2>
                  <div className="mt-5 divide-y divide-white/8 border-y border-white/8">
                    {model.faq.map((item) => (
                      <details key={item.question} className="group py-4">
                        <summary className={`flex cursor-pointer list-none items-center justify-between gap-4 text-sm font-semibold text-white/84 marker:hidden ${focusRing}`}>{item.question}<ChevronRight className="h-4 w-4 shrink-0 text-white/32 transition group-open:rotate-90" /></summary>
                        <p className="max-w-2xl pt-3 text-sm leading-7 text-white/50">{item.answer}</p>
                      </details>
                    ))}
                  </div>
                </section>
              ) : null}

              {reviews.length ? <ReviewsSection reviews={reviews} listingId={listing.id} onReviewAdded={onReviewAdded} /> : null}

              {relatedListings.length ? (
                <section aria-labelledby="related-title">
                  <h2 id="related-title" className="text-2xl font-semibold tracking-[-0.025em] text-white">More to explore</h2>
                  <div className="mt-5 grid gap-3 sm:grid-cols-2">
                    {relatedListings.slice(0, 4).map((item) => (
                      <Link key={item.id} to={`/listing/${encodeURIComponent(item.id)}`} className={`group flex min-w-0 items-center justify-between gap-3 rounded-2xl border border-white/8 bg-white/[0.02] p-4 transition hover:bg-white/[0.045] ${focusRing}`}>
                        <div className="min-w-0"><p className="truncate text-sm font-semibold text-white/80 group-hover:text-white">{item.title || 'Wersee product'}</p>{item.category ? <p className="mt-1 truncate text-xs text-white/34">{item.category}</p> : null}</div><ChevronRight className="h-4 w-4 shrink-0 text-white/25" />
                      </Link>
                    ))}
                  </div>
                </section>
              ) : null}

              {accessState !== 'owner' ? (
                <button type="button" onClick={() => setReportOpen(true)} className={`inline-flex min-h-11 items-center gap-2 text-xs font-medium text-white/32 transition hover:text-red-200 ${focusRing}`}><Flag className="h-3.5 w-3.5" /> Report this listing</button>
              ) : null}
            </div>
          </div>

          <div className="hidden lg:block">
            <div className="sticky top-24">
              <PurchasePanel
                cta={cta}
                currency={currency}
                inclusions={purchaseInclusions}
                isOnSale={!selectedPlan && pricing.isOnSale === true}
                originalPrice={!selectedPlan && Number.isFinite(Number(pricing.originalPrice)) ? Number(pricing.originalPrice) : null}
                plans={model.plans}
                price={price}
                priceSuffix={priceSuffix}
                selectedPlanIndex={selectedPlanIndex}
                delivery={model.delivery}
                refund={model.refund}
                onPrimaryAction={runPrimaryAction}
                onRetryAccess={onRetryAccess}
                onSelectPlan={setSelectedPlanIndex}
              />
            </div>
          </div>
        </div>
      </main>

      <PublicStoreFooter sellerName={sellerName} sellerPath={sellerPath} />

      {typeof document !== 'undefined' ? createPortal(
        <div className="fixed inset-x-0 bottom-0 z-50 border-t border-white/10 bg-[#0b0b0e]/94 px-3 pt-3 shadow-[0_-20px_55px_rgba(0,0,0,.38)] backdrop-blur-2xl lg:hidden" style={{ paddingBottom: 'max(0.75rem, env(safe-area-inset-bottom, 0px))' }}>
          <div className="mx-auto flex max-w-xl items-center gap-3">
            <div className="min-w-0 flex-1">
              <p className="truncate text-[11px] font-medium text-white/38">{selectedPlan?.name || (isSubscription ? 'Recurring access' : 'Product access')}</p>
              <p className="truncate text-base font-semibold text-white">{price === null ? 'Unavailable' : price === 0 ? 'Free' : <LocalizedPrice amount={price} baseCurrency={currency} />}</p>
            </div>
            <button type="button" disabled={cta.disabled} onClick={runPrimaryAction} aria-describedby={cta.reason ? 'product-cta-reason' : undefined} className={`flex min-h-12 min-w-[148px] items-center justify-center rounded-xl bg-white px-5 text-sm font-semibold text-black transition active:translate-y-px disabled:cursor-not-allowed disabled:bg-white/10 disabled:text-white/38 ${focusRing}`}>{cta.label}</button>
          </div>
        </div>,
        document.body,
      ) : null}

      <ReportModal
        isOpen={reportOpen}
        onClose={() => setReportOpen(false)}
        reportedUserId={listing.seller_id}
        listingId={listing.id}
        title="Report Listing"
      />
    </div>
  );
};
